function item(
  stem: string,
  correct: string,
  wrong: [string, string, string],
  kind:
    | 'air-france'
    | 'flotte'
    | 'pionniers'
    | 'histoire'
    | 'records'
    | 'aeroports'
    | 'navigation',
  explain: string,
) {
  return { stem, choices: [correct, ...wrong] as [string, string, string, string], correct: 0, kind, explain };
}

